#!/usr/bin/env node
// The Hours Back calling screen.
//
// Four screens:
//   /            today — callbacks first, follow-ups due, the week's score
//   /list        every business, best first, searchable
//   /business/x  the account card: everything known, everything editable
//   /call/x      the three questions after a dial
//
// Anything typed here outranks anything fetched, forever, and every
// correction is kept with who made it and when.
const http = require('http');
const fs = require('fs');
process.chdir(require('path').resolve(__dirname, '../..'));
// Local convenience only: read .env when it exists. On a host there is no
// .env — the settings arrive as real environment variables — and a missing
// file must never crash the app. (It did: first deploy died here.)
try {
  for (const line of fs.readFileSync('.env', 'utf8').split('\n')) {
    const m = line.match(/^([A-Z_]+)="?([^"]*)"?$/);
    if (m && process.env[m[1]] === undefined) process.env[m[1]] = m[2];
  }
} catch { /* no .env on the host — expected */ }
const { PrismaClient } = require('@prisma/client');
const { callQueue, followUpQueue, callToPaidReadout } = require('../../src/hoursback/crm/queues.js');
const { logCall, leakReport } = require('../../src/hoursback/crm/nextAction.js');
const { markDoNotContact, CALL_OUTCOMES } = require('../../src/hoursback/crm/stages.js');
const { freezeQuote } = require('../../src/hoursback/crm/quote.js');
const { setOverride, resolveField, OVERRIDABLE } = require('../../src/hoursback/overrides.js');
const L = require('../../src/hoursback/crm/lanes.js');
const { draftFirstContact, draftLinkedIn, BODY: TEMPLATE_BODY, SUBJECTS } = require('../../src/hoursback/crm/firstContact.js');
const { refreshProspect } = require('../../src/hoursback/refresh.js');
const { forTrade } = require('../../src/hoursback/scenarios.js');
const db = new PrismaClient();

// Businesses whose website is being read right now. Reading a site takes up to
// forty seconds, so a save never waits on it — it starts the work, redirects
// straight away, and the card shows that it is happening and refreshes itself
// when it is done.
const BUSY = new Set();
function refreshInBackground(id) {
  if (BUSY.has(id)) return;
  BUSY.add(id);
  refreshProspect(db, id)
    .catch((e) => console.error('refresh failed for', id, e.message))
    .finally(() => BUSY.delete(id));
}

const OUTCOME_LABELS = {
  NO_ANSWER: 'No answer', VOICEMAIL: 'Left voicemail', GATEKEEPER: 'Gatekeeper',
  WRONG_NUMBER: 'Wrong number', NOT_INTERESTED: 'Not interested', INTERESTED: 'Interested!',
};
const SITE_STATUS_LABELS = {
  READ: 'website read', NO_WEBSITE: 'no website', UNREACHABLE: 'website would not load',
  // The site opened and published nothing we could keep — a robot check, or
  // pages built entirely by script. Not a read, and it says so (2026-09-02).
  UNREADABLE: 'website opened but gave up no words',
};
const EMAIL_STATUS_LABELS = {
  FOUND_ON_SITE: 'found on their site', FOUND_LOW_CONFIDENCE: 'found, but might be wrong',
  UNAVAILABLE_NO_WEBSITE: 'no website to look at', UNAVAILABLE_NOT_PUBLISHED: 'not published anywhere',
  UNAVAILABLE_SITE_UNREACHABLE: 'site would not load',
};

// What a business IS, in one line, for every list. Russ asked why the lists
// showed a price and a band label but never the trade or the team size — the
// two things that actually tell him who he is looking at (2026-08-26).
const TRADE_OPTIONS = Object.keys(require('../../src/hoursback/industryTiers.js').ADMIN_SHARE).sort();

// The order of the email list, held still between visits. One entry per filter
// combination, thrown away when the app restarts — it is a convenience, not a
// record, and a fresh start should give a fresh ranking.
const HELD_ORDER = new Map();

// His own rewrites, in memory before the first message is drafted.
require('../../src/hoursback/crm/campaign.js').loadHisWordings(db)
  .then((n) => { if (n) console.log(`${n} of your own wordings in use`); })
  .catch(() => { /* the table may not exist on an older copy */ });
function tradeOfName(p) {
  const { tradeOf } = require('../../src/hoursback/crm/queues.js');
  return tradeOf(resolveField(p, 'name'));
}

function whoTheyAre(p) {
  const { tradeOf } = require('../../src/hoursback/crm/queues.js');
  const trade = p.trade || tradeOf(resolveField(p, 'name'));
  const n = resolveField(p, 'employeeCount');
  const size = n ? `${n} people` : 'team size unknown';
  return `${trade} · ${size}`;
}

const esc = (v) => String(v === null || v === undefined ? '' : v)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const digits = (v) => String(v || '').replace(/\D/g, '');

